import sys

n, k = map(int, sys.stdin.read().split())
res = []

def ok(pos, c):
    r = len(pos)
    for rr, cc in enumerate(pos):
        if cc == c or abs(cc - c) == r - rr:
            return False
    return True

def go(pos):
    if len(pos) == n:
        res.append(pos[:])
        return
    for c in range(n):
        if ok(pos, c):
            pos.append(c)
            go(pos)
            pos.pop()

go([])
print(len(res))
for p in res[:k]:
    print(' '.join(str(c + 1) for c in p))

